INSERT INTO task_type_template (type_id, locale, render_target, template_text, spec_version)
VALUES
    ('G10-FUN-002', 'ru-KZ', 'plaintext', 'Найдите обратную функцию f⁻¹(x), если f(x) = {{a}}x + {{b}}.', '1.0.0-draft'),
    ('G10-FUN-003', 'ru-KZ', 'plaintext', 'Сдвигает ли график функции f(x − {{h}}) + {{k}} график вверх? Ответьте true или false.', '1.0.0-draft'),
    ('G10-PRO-001', 'ru-KZ', 'plaintext', 'Какова вероятность выпадения числа {{face}} при броске правильного игрального кубика с шестью гранями?', '1.0.0-draft'),
    ('G10-PRO-002', 'ru-KZ', 'plaintext', 'События A и B независимы; P(A) = {{p1}}, P(B) = {{p2}}. Найдите P(A {{operation}} B).', '1.0.0-draft'),
    ('G10-PRO-003', 'ru-KZ', 'plaintext', 'Исследователь выбирает каждое {{interval}}-е имя из полного списка, начиная со случайно выбранного места. Является ли такая выборка случайной? Ответьте true или false.', '1.0.0-draft'),
    ('G10-PRO-004', 'ru-KZ', 'plaintext', 'Для исследования из каждой {{group}} населения выбирают одинаковое число участников. Обеспечивает ли такой способ представительность выборки? Ответьте true или false.', '1.0.0-draft'),
    ('G10-PRO-005', 'ru-KZ', 'plaintext', 'Правильную монету подбрасывают {{trials}} раза. Найдите вероятность того, что оба раза выпадет орёл.', '1.0.0-draft'),
    ('G10-PRO-006', 'ru-KZ', 'plaintext', 'Верна ли вероятностная модель, если вероятности всех возможных исходов равны {{probabilities}}? Ответьте true или false.', '1.0.0-draft'),
    ('G10-PRO-007', 'ru-KZ', 'plaintext', 'Для событий A и B заданы P(A) = {{a}}, P(B) = {{b}} и P(A ∩ B) = {{both}}. Независимы ли события A и B? Ответьте true или false.', '1.0.0-draft'),
    ('G10-PRO-008', 'ru-KZ', 'plaintext', 'Среди {{n}} объектов {{m}} являются благоприятными. Случайно выбирают {{k}} объектов. Найдите вероятность выбора благоприятного объекта.', '1.0.0-draft'),
    ('G10-PRO-009', 'ru-KZ', 'plaintext', 'В игре выплата 0 баллов происходит с вероятностью {{p0}}, а выплата 10 баллов — с вероятностью {{p10}}. Найдите математическое ожидание выплаты.', '1.0.0-draft'),
    ('G10-STA-001', 'ru-KZ', 'plaintext', 'Теоретическая вероятность равна {{p}}, а экспериментальная — {{q}}. Найдите разность теоретической и экспериментальной вероятностей.', '1.0.0-draft')
